import { createHash } from 'node:crypto';
import bcrypt from 'bcryptjs';
import { NextRequest, NextResponse } from 'next/server';
import { createSession, SESSION_COOKIE, SESSION_MAX_AGE_SECONDS, type AccountRole } from '@/lib/auth';
